const { app, BrowserWindow, Menu, dialog, session } = require("electron");
const path = require("path");
const fs = require("fs");
const crypto = require("crypto");
const { pathToFileURL } = require("url");
const { spawn } = require("child_process");

app.setName("Simple POS");

// Load root .env if present without requiring external dependencies
function loadEnvFile(envPath) {
  try {
    if (!fs.existsSync(envPath)) return;
    const content = fs.readFileSync(envPath, "utf8");
    for (const rawLine of content.split(/\r?\n/)) {
      const line = rawLine.trim();
      if (!line || line.startsWith("#")) continue;
      const eqIndex = line.indexOf("=");
      if (eqIndex === -1) continue;
      const key = line.slice(0, eqIndex).trim();
      const value = line
        .slice(eqIndex + 1)
        .trim()
        .replace(/^['"]|['"]$/g, "");
      if (key && process.env[key] === undefined) {
        process.env[key] = value;
      }
    }
  } catch (error) {
    console.warn("Could not read .env file:", error.message);
  }
}

const isDev = !app.isPackaged;
if (isDev) {
  loadEnvFile(path.resolve(__dirname, "../../.env"));
}

const BACKEND_HOST = isDev
  ? process.env.BACKEND_HOST || "127.0.0.1"
  : "127.0.0.1";
const BACKEND_PORT = isDev ? process.env.BACKEND_PORT || "5000" : "5000";
const FRONTEND_HOST = process.env.FRONTEND_HOST || "127.0.0.1";
const FRONTEND_PORT = process.env.FRONTEND_PORT || "5173";

const HEALTH_URL = `http://${BACKEND_HOST}:${BACKEND_PORT}/api/health`;
const AUTH_CHECK_URL = `http://${BACKEND_HOST}:${BACKEND_PORT}/api/settings`;
const DEV_FRONTEND_URL = `http://${FRONTEND_HOST}:${FRONTEND_PORT}`;

let mainWindow = null;
let backendProcess = null;
let logStream = null;
const localApiToken = isDev
  ? process.env.LOCAL_API_TOKEN
  : crypto.randomBytes(32).toString("hex");
const additionalArguments = [
  `--api-base-url=http://${BACKEND_HOST}:${BACKEND_PORT}`,
];

if (isDev && localApiToken) {
  additionalArguments.push(`--local-api-token=${localApiToken}`);
}

// Enforce single application instance
const gotSingleInstanceLock = app.requestSingleInstanceLock();

if (!gotSingleInstanceLock) {
  app.quit();
} else {
  app.on("second-instance", () => {
    if (mainWindow) {
      if (mainWindow.isMinimized()) {
        mainWindow.restore();
      }
      mainWindow.focus();
    }
  });

  app.whenReady().then(async () => {
    if (!isDev) {
      Menu.setApplicationMenu(null);
    }

    startBackend();

    const backendReady = await waitForBackend();

    if (!backendReady) {
      dialog.showErrorBox(
        "Simple POS could not start",
        `The local backend server (${HEALTH_URL}) did not become available within 30 seconds. Please restart the application.`,
      );

      app.quit();
      return;
    }

    createWindow();

    app.on("activate", () => {
      if (BrowserWindow.getAllWindows().length === 0) {
        createWindow();
      }
    });
  });
}

function startBackend() {
  if (isDev) {
    // In development, npm run dev starts the backend concurrently.
    return;
  }

  const nodeExecutable = path.join(process.resourcesPath, "node", "node.exe");
  const backendEntry = path.join(
    process.resourcesPath,
    "backend",
    "src",
    "server.js",
  );

  const userDataDir = app.getPath("userData");
  fs.mkdirSync(userDataDir, { recursive: true });

  const logFilePath = path.join(userDataDir, "backend.log");
  logStream = fs.createWriteStream(logFilePath, { flags: "a" });

  const env = {
    ...process.env,
    POS_DATA_DIR: userDataDir,
    POS_PACKAGED: "1",
    HOST: BACKEND_HOST,
    PORT: String(BACKEND_PORT),
    LOCAL_API_TOKEN: localApiToken,
  };

  backendProcess = spawn(nodeExecutable, [backendEntry], {
    cwd: path.join(process.resourcesPath, "backend"),
    env,
    stdio: ["ignore", "pipe", "pipe"],
    windowsHide: true,
  });

  if (backendProcess.stdout && logStream) {
    backendProcess.stdout.pipe(logStream, { end: false });
  }

  if (backendProcess.stderr && logStream) {
    backendProcess.stderr.pipe(logStream, { end: false });
  }

  backendProcess.on("error", (error) => {
    console.error("Failed to start backend:", error);
    if (logStream) {
      logStream.write(
        `[${new Date().toISOString()}] Failed to start backend: ${error.stack || error.message}\n`,
      );
    }
  });

  backendProcess.on("exit", (code) => {
    console.log("Backend process exited with code:", code);
    if (logStream) {
      logStream.write(
        `[${new Date().toISOString()}] Backend process exited with code: ${code}\n`,
      );
    }
    backendProcess = null;
  });
}

async function waitForBackend(timeoutMs = 30000) {
  const startTime = Date.now();

  while (Date.now() - startTime < timeoutMs) {
    try {
      const response = await fetch(HEALTH_URL);

      if (response.ok) {
        const authCheck = await fetch(AUTH_CHECK_URL, {
          headers: {
            "X-Local-API-Token": localApiToken || "",
          },
        });

        if (authCheck.ok) {
          return true;
        }
      }
    } catch {
      // Backend is still starting; retry after a short pause.
    }

    await new Promise((resolve) => setTimeout(resolve, 400));
  }

  return false;
}

function createWindow() {
  const iconPath = path.join(__dirname, "../../build/icon.ico");

  if (!isDev) {
    const apiUrlPattern = `http://${BACKEND_HOST}:${BACKEND_PORT}/api/*`;

    session.defaultSession.webRequest.onBeforeSendHeaders(
      { urls: [apiUrlPattern] },
      (details, callback) => {
        const headers = { ...details.requestHeaders };

        for (const name of Object.keys(headers)) {
          if (name.toLowerCase() === "x-local-api-token") {
            delete headers[name];
          }
        }

        headers["X-Local-API-Token"] = localApiToken;
        callback({ requestHeaders: headers });
      },
    );
  }

  mainWindow = new BrowserWindow({
    width: 1400,
    height: 900,
    minWidth: 1000,
    minHeight: 650,
    title: "Simple POS",
    icon: fs.existsSync(iconPath) ? iconPath : undefined,
    autoHideMenuBar: true,
    webPreferences: {
      preload: path.join(__dirname, "preload.js"),
      contextIsolation: true,
      nodeIntegration: false,
      additionalArguments,
    },
  });

  const trustedRendererUrl = isDev
    ? DEV_FRONTEND_URL
    : pathToFileURL(
        path.join(__dirname, "../../frontend/dist/index.html"),
      ).href;

  mainWindow.webContents.on("will-navigate", (event, url) => {
    if (
      url !== trustedRendererUrl &&
      !url.startsWith(`${trustedRendererUrl}#`)
    ) {
      event.preventDefault();
    }
  });
  mainWindow.webContents.setWindowOpenHandler(() => ({ action: "deny" }));

  if (isDev) {
    mainWindow.loadURL(DEV_FRONTEND_URL);
  } else {
    mainWindow.loadFile(path.join(__dirname, "../../frontend/dist/index.html"));
  }

  mainWindow.on("page-title-updated", (event) => {
    event.preventDefault();
    mainWindow.setTitle("Simple POS");
  });

  mainWindow.on("closed", () => {
    mainWindow = null;
  });
}

app.on("before-quit", () => {
  if (backendProcess && !backendProcess.killed) {
    backendProcess.kill();
    backendProcess = null;
  }

  if (logStream) {
    logStream.end();
    logStream = null;
  }
});

app.on("window-all-closed", () => {
  if (process.platform !== "darwin") {
    app.quit();
  }
});
